static State integrate(State s,double time){const int steps=int(std::ceil(std::abs(time)/.1));const double h=time/steps;for(int step=0;step<steps;++step){auto k1=derivative(s);State p{};for(int i=0;i<6;++i)p[i]=s[i]+h*k1[i]/2;auto k2=derivative(p);for(int i=0;i<6;++i)p[i]=s[i]+h*k2[i]/2;auto k3=derivative(p);for(int i=0;i<6;++i)p[i]=s[i]+h*k3[i];auto k4=derivative(p);for(int i=0;i<6;++i)s[i]+=h*(k1[i]+2*k2[i]+2*k3[i]+k4[i])/6;}return s;}
